import collections,json,re,subprocess,hashlib
from pathlib import Path
D=Path(__file__).resolve().parent;R=D.parents[6];O=R/'runs/screen/p3a_early';rows=[];cells=json.load(open(D/'cells.json'));base=json.load(open(D.parent/'counts.json'))['rows'];occ=R/'runs/screen/p3a_ladder/occ'
for i in (1,2):
 p=O/f'ear{i}.cu';assert hashlib.sha256(p.read_bytes()).hexdigest()==cells[f'ear{i}']['cuda_sha256'];z=subprocess.run(['nvcc','-O3','-std=c++20','-gencode=arch=compute_90a,code=sm_90a','-c',str(p),'-o',str(p.with_suffix('.o')),'-Xptxas=-v'],text=True,capture_output=True);p.with_suffix('.log').write_text(z.stdout+z.stderr);z.check_returncode();sass=subprocess.check_output(['cuobjdump','--dump-sass',str(p.with_suffix('.o'))],text=True);p.with_suffix('.sass').write_text(sass);fn,body=next((f,b) for f,b in re.findall(r'Function : (\S+)\n(.*?)(?=\n\s*Function : |\Z)',sass,re.S) if 'moe_varILi1ELi69E' in f);log=z.stdout+z.stderr;v=re.search(r'Function properties for '+re.escape(fn)+r'\n\s*(\d+) bytes stack frame, (\d+) bytes spill stores, (\d+) bytes spill loads\nptxas info\s*:\s*Used (\d+) registers',log);stack,ss,sl,reg=map(int,v.groups());assert stack==ss==sl==0 and reg<=128;ops=dict(collections.Counter(x.split('.')[0] for x in re.findall(r'/\*[0-9a-f]+\*/\s+(?:@!?U?P\d+\s+)?([A-Z][A-Z0-9_.]+)',body)));assert ops['HMMA']==32 and ops['HMUL2']==128
 for M in ([8] if i==1 else [16,32]):
  control=next(v for v in base if v['M']==M and v['arm']=='BASE');res=int(subprocess.check_output([str(occ),str(reg),str(control['shared']),'0'],text=True));assert res==2;rows.append(dict(M=M,arm='EARLY',registers=reg,stack=stack,spill_stores=ss,spill_loads=sl,shared=control['shared'],static=0,resident=res,ops=ops,cell_sha256=cells[f'ear{i}']['cell_sha256'],cuda_sha256=cells[f'ear{i}']['cuda_sha256']))
 print(i,reg,stack,ss,sl,'2CTA',flush=True)
rows.append(dict(next(v for v in base if v['M']==1 and v['arm']=='BASE'),arm='EARLY',control_alias=True));(D/'counts.json').write_text(json.dumps(dict(rows=rows,all_twoCTA=True,all_zero_spills=True),indent=2)+'\n')
